package studio.jiayu.runtime;
import studio.jiayu.matrix.*;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Packaged project runtime. No host keys or host filesystem access. */
public class RuntimeActivity extends Activity {
 static final String ORIGIN="https://app.neo.local/";
 WebView web;JSONObject meta;JSONArray logs=new JSONArray(),tests=new JSONArray();ValueCallback<Uri[]> chooser;
 PermissionRequest permission;String[] mediaResources;String aiId;boolean debugMode;byte[] saveBytes;
 @Override public void onCreate(Bundle b){super.onCreate(b);MatrixDevice.recover(this);try{meta=new JSONObject(read("project.json"));}catch(Exception e){meta=new JSONObject();}
  getWindow().getDecorView();getWindow().setDecorFitsSystemWindows(false);getWindow().setNavigationBarContrastEnforced(false);getWindow().setStatusBarColor(Color.TRANSPARENT);getWindow().setNavigationBarColor(Color.TRANSPARENT);getWindow().getInsetsController().setSystemBarsAppearance(24,24);
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff8fafc);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{Insets s=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()),k=i.getInsets(WindowInsets.Type.ime());root.setPadding(s.left,s.top,s.right,Math.max(s.bottom,k.bottom));return WindowInsets.CONSUMED;});
  LinearLayout bar=new LinearLayout(this);TextView title=new TextView(this);title.setText(meta.optString("name","Neo App"));title.setTextColor(0xff173d35);title.setPadding(24,10,0,10);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button menu=new Button(this);menu.setText("⋯");menu.setContentDescription("应用与调试");menu.setOnClickListener(v->menu());bar.addView(menu,new LinearLayout.LayoutParams(150,150));root.addView(bar);
  web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);web.addJavascriptInterface(new NativeBridge(),"NeoNative");
  WebView.setWebContentsDebuggingEnabled((getApplicationInfo().flags&2)!=0);
  web.setWebViewClient(new WebViewClient(){
   @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!"app.neo.local".equals(u.getHost()))return null;try{String f=u.getPath().substring(1);if(f.isEmpty())f="index.html";if(f.contains("/")||f.contains(".."))throw new IOException();String mime=f.endsWith("html")?"text/html":f.endsWith("js")?"text/javascript":f.endsWith("css")?"text/css":f.endsWith("svg")?"image/svg+xml":"text/plain";byte[] data;if(f.equals("neo-runtime.js"))data=helper().getBytes(StandardCharsets.UTF_8);else{String text=read("project/"+f);if(f.equals("index.html")){String script="<script src=\"neo-runtime.js\"></script>";text=text.contains("</head>")?text.replace("</head>",script+"</head>"):script+text;}data=text.getBytes(StandardCharsets.UTF_8);}Map<String,String> headers=new HashMap<>();headers.put("Content-Security-Policy","default-src 'self' data: blob:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src https: blob:; img-src 'self' data: blob: https:; media-src 'self' blob:; frame-src 'none'; object-src 'none'; base-uri 'none'");return new WebResourceResponse(mime,"UTF-8",200,"OK",headers,new ByteArrayInputStream(data));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not found",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}}
   @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if(ORIGIN.equals(r.getUrl().toString())||r.getUrl().toString().startsWith(ORIGIN))return false;if(r.isForMainFrame()&&"https".equals(r.getUrl().getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,r.getUrl()));}catch(Exception ignored){}return true;}
  });
  web.setWebChromeClient(new WebChromeClient(){
   @Override public boolean onConsoleMessage(ConsoleMessage m){if(m.messageLevel()==ConsoleMessage.MessageLevel.ERROR)addLog("error",m.message());return true;}
   @Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;try{startActivityForResult(p.createIntent().addCategory(Intent.CATEGORY_OPENABLE),20);}catch(Exception e){cb.onReceiveValue(null);chooser=null;}return true;}
   @Override public void onPermissionRequest(PermissionRequest p){runOnUiThread(()->askMedia(p));}
   @Override public void onPermissionRequestCanceled(PermissionRequest p){if(permission==p)permission=null;}
  });
  web.setDownloadListener((url,ua,cd,mime,size)->{if(url.startsWith("blob:")){web.evaluateJavascript("fetch("+JSONObject.quote(url)+").then(r=>r.blob()).then(b=>{if(b.size>1048576)throw Error('文件超过1MB');let f=new FileReader();f.onload=()=>NeoNative.save(f.result,'neo-report.json');f.readAsDataURL(b)})",null);}else if(url.startsWith("data:"))new NativeBridge().save(url,"neo-report.json");});
  web.loadUrl(ORIGIN+"index.html");addLog("lifecycle","应用启动");
 }
 String read(String f)throws Exception{try(InputStream in=getAssets().open(f);ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)o.write(b,0,n);return o.toString("UTF-8");}}
 String helper(){return "(()=>{const pending=new Map();window.NeoDev={info:()=>JSON.parse(NeoNative.info()),log:(level,text)=>NeoNative.log(String(level),String(text)),test:(name,status,detail='')=>NeoNative.test(String(name),String(status),String(detail)),report:()=>NeoNative.report(),ai:prompt=>new Promise((resolve,reject)=>{const id=Date.now()+'-'+Math.random();pending.set(id,{resolve,reject});NeoNative.ai(id,String(prompt));})};window.addEventListener('neo-runtime',e=>{let p=pending.get(e.detail.id);if(p){pending.delete(e.detail.id);e.detail.error?p.reject(Error(e.detail.error)):p.resolve(e.detail.result)}});window.addEventListener('error',e=>NeoDev.log('error',e.message));window.addEventListener('unhandledrejection',e=>NeoDev.log('error',String(e.reason)));})();";}
 String redact(String s){return s.replaceAll("(?i)(sk-[A-Za-z0-9_-]{12,}|Bearer\\s+[A-Za-z0-9._-]+)","[已隐藏密钥]");}
 synchronized void addLog(String level,String text){try{if(logs.length()>=100)logs.remove(0);logs.put(new JSONObject().put("time",System.currentTimeMillis()).put("level",level).put("text",redact(text.length()>1000?text.substring(0,1000):text)));}catch(Exception ignored){}}
 JSONObject reportData()throws Exception{return new JSONObject().put("schema","neo-debug/1").put("projectId",meta.optString("id")).put("appId",getPackageName()).put("version",getPackageManager().getPackageInfo(getPackageName(),0).versionName).put("time",System.currentTimeMillis()).put("events",logs).put("tests",tests);}
 void menu(){new AlertDialog.Builder(this).setTitle(meta.optString("name")).setItems(new String[]{debugMode?"关闭调试模式":"开启调试模式","查看运行日志","回传调试报告到 Neo Studio","导出调试报告 JSON","重新加载"},(d,n)->{if(n==0){debugMode=!debugMode;toast(debugMode?"调试模式已开启":"调试模式已关闭");}if(n==1)try{new AlertDialog.Builder(this).setMessage(reportData().toString(2)).setPositiveButton("关闭",null).show();}catch(Exception ignored){}if(n==2)sendReport();if(n==3)try{saveBytes=reportData().toString(2).getBytes(StandardCharsets.UTF_8);savePicker("neo-debug.json");}catch(Exception ignored){}if(n==4)web.reload();}).show();}
 void sendReport(){if(!debugMode){toast("请先在菜单开启调试模式");return;}try{String report=reportData().toString();new AlertDialog.Builder(this).setTitle("回传调试报告").setMessage("将版本、自检与错误日志交给 Neo Studio。请先在“查看运行日志”中核对内容，不会发送照片、音频或 API Key。").setPositiveButton("回传",(d,n)->{try{startActivityForResult(new Intent("studio.jiayu.neo.DEBUG_REPORT").setClassName("studio.jiayu.neo","studio.jiayu.neo.IntegrationActivity").putExtra("report",report),31);}catch(Exception e){toast("请安装 Neo Studio，或先导出 JSON");}}).setNegativeButton("取消",null).show();}catch(Exception e){toast("报告生成失败");}}
 void askMedia(PermissionRequest p){if(!"https".equals(p.getOrigin().getScheme())||!"app.neo.local".equals(p.getOrigin().getHost())){p.deny();return;}List<String> resources=new ArrayList<>(),perms=new ArrayList<>();for(String r:p.getResources()){if(r.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE)){resources.add(r);perms.add(Manifest.permission.CAMERA);}if(r.equals(PermissionRequest.RESOURCE_AUDIO_CAPTURE)){resources.add(r);perms.add(Manifest.permission.RECORD_AUDIO);}}if(resources.isEmpty()){p.deny();return;}permission=p;mediaResources=resources.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("申请设备权限").setMessage("此应用希望使用"+(perms.contains(Manifest.permission.CAMERA)?"摄像头 ":"")+(perms.contains(Manifest.permission.RECORD_AUDIO)?"麦克风":"")+"。是否继续？").setPositiveButton("继续",(d,n)->requestPermissions(perms.toArray(new String[0]),10)).setNegativeButton("拒绝",(d,n)->{p.deny();permission=null;}).setOnCancelListener(d->{p.deny();permission=null;}).show();}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==10&&permission!=null){List<String>a=new ArrayList<>();for(String s:mediaResources)if(checkSelfPermission(s.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE)?Manifest.permission.CAMERA:Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)a.add(s);if(a.isEmpty())permission.deny();else permission.grant(a.toArray(new String[0]));permission=null;}}
 final class NativeBridge{
  @JavascriptInterface public boolean matrixNative(){return MatrixDevice.available(RuntimeActivity.this);}
  @JavascriptInterface public String matrixStatus(){return MatrixService.status(RuntimeActivity.this);}
  @JavascriptInterface public void matrix(String action,String payload){runOnUiThread(()->{try{if(action.equals("start")){JSONObject p=new JSONObject(payload);MatrixService.start(RuntimeActivity.this,read("project/neo-matrix.json"),p.optBoolean("simulate"),p.optBoolean("keepLit",true));}else if(action.equals("stop"))startService(new Intent(RuntimeActivity.this,MatrixService.class).setAction("stop"));else if(action.equals("settings"))MatrixSettings.show(RuntimeActivity.this);else if(action.equals("permissions"))MatrixSettings.permissions(RuntimeActivity.this);}catch(Exception e){toast(e.getMessage());addLog("matrix",e.getMessage());}});}

  @JavascriptInterface public String info(){try{return new JSONObject().put("projectId",meta.optString("id")).put("appId",getPackageName()).put("version",getPackageManager().getPackageInfo(getPackageName(),0).versionName).put("sdk",Build.VERSION.SDK_INT).put("buildRoute","offline-device").toString();}catch(Exception e){return "{}";}}
  @JavascriptInterface public void log(String level,String text){addLog(level,text);}
  @JavascriptInterface public void test(String name,String status,String detail){if(name.length()>100||detail.length()>1000)return;runOnUiThread(()->{try{if(tests.length()>=50)tests.remove(0);tests.put(new JSONObject().put("name",name).put("status",status).put("detail",redact(detail)));}catch(Exception ignored){}});}
  @JavascriptInterface public void report(){runOnUiThread(()->sendReport());}
  @JavascriptInterface public void ai(String id,String prompt){runOnUiThread(()->{if(prompt.length()>4000||aiId!=null){reply(id,null,"请求过长或已有请求进行中");return;}aiId=id;try{startActivityForResult(new Intent("studio.jiayu.neo.AI_REQUEST").setClassName("studio.jiayu.neo","studio.jiayu.neo.IntegrationActivity").putExtra("projectId",meta.optString("id")).putExtra("prompt",prompt),30);}catch(Exception e){aiId=null;reply(id,null,"请先安装 Neo Studio 并配置 API");}});}
  @JavascriptInterface public void save(String data,String name){if(data.length()>1500000)return;runOnUiThread(()->{try{int c=data.indexOf(',');if(c<0||!data.substring(0,c).endsWith(";base64"))throw new Exception();saveBytes=android.util.Base64.decode(data.substring(c+1),0);savePicker(name.matches("[A-Za-z0-9_.-]{1,80}")?name:"neo-export.json");}catch(Exception e){toast("导出内容无效");}});}
 }
 void reply(String id,JSONObject result,String error){try{JSONObject e=new JSONObject().put("id",id);if(error!=null)e.put("error",error);else e.put("result",result);web.evaluateJavascript("window.dispatchEvent(new CustomEvent('neo-runtime',{detail:"+e+"}))",null);}catch(Exception ignored){}}
 void savePicker(String name){startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name),21);}
 @Override public void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(r==20&&chooser!=null){chooser.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(code,data));chooser=null;}if(r==21&&code==RESULT_OK&&data!=null)try(OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(saveBytes);toast("已保存");}catch(Exception e){toast("保存失败");}if(r==21)saveBytes=null;if(r==30){String id=aiId;aiId=null;try{if(code!=RESULT_OK||data==null)reply(id,null,"请求取消");else{JSONObject res=new JSONObject(data.getStringExtra("result"));reply(id,res,res.optString("error",null));}}catch(Exception e){reply(id,null,"接口结果无效");}}if(r==31)toast(code==RESULT_OK?"调试报告已交给 Neo Studio":"回传未完成");}
 void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
 @Override public void onPause(){if(web!=null){web.evaluateJavascript("window.dispatchEvent(new Event('blur'));document.querySelectorAll('video,audio').forEach(e=>{if(e.srcObject)e.srcObject.getTracks().forEach(t=>t.stop())});window.dispatchEvent(new Event('neo-background'))",null);web.onPause();}super.onPause();}
 @Override public void onResume(){super.onResume();if(web!=null)web.onResume();}
 @Override public void onDestroy(){if(chooser!=null)chooser.onReceiveValue(null);if(permission!=null)permission.deny();if(web!=null){web.removeJavascriptInterface("NeoNative");web.destroy();}super.onDestroy();}
}
